//! crypt-io 1.5.0: one-time passwords, ECDSA P-256 checks and COSE keys,
//! against published vectors.
//!
//! - HOTP: RFC 4226 appendix D, codes and HMAC-SHA1 intermediates.
//! - TOTP: RFC 6238 appendix B, the SHA-1 rows.
//! - ECDSA P-256 SHA-256: NIST CAVP 186-4 SigVer (P-256, SHA-256) with
//!   NIST's verdicts; Wycheproof DER and IEEE P1363 files.
//! - WebAuthn Level 3 section 16: every credential key with its
//!   assertion signature (ES256, RS256, EdDSA; ES384, ES512 and Ed448
//!   must be refused).
//!
//! `tests/data/v15_vectors.rs` is generated by
//! `tests/data/gen_v15_vectors.py`.

#![cfg(any(
    feature = "otp",
    feature = "sign-p256",
    feature = "sign-ed25519",
    feature = "sign-rsa"
))]
#![allow(clippy::unwrap_used, clippy::expect_used)]

#[path = "data/v15_vectors.rs"]
mod vectors;

use crypt_io::Error;

fn h(s: &str) -> Vec<u8> {
    hex::decode(s).expect("valid hex")
}

#[cfg(feature = "otp")]
mod otp {
    use super::{Error, h, vectors};
    use crypt_io::otp;
    use proptest::prelude::*;

    #[test]
    fn rfc4226_hotp_and_hmac_sha1() {
        for &(counter, mac, code) in vectors::RFC4226 {
            assert_eq!(
                otp::hmac_sha1_legacy(vectors::OTP_SECRET, &counter.to_be_bytes()).as_slice(),
                h(mac),
                "counter {counter}"
            );
            assert_eq!(otp::hotp(vectors::OTP_SECRET, counter, 6).unwrap(), code);
            let typed = format!("{code:06}");
            // Found from counter 0 with enough look-ahead, at its own counter.
            let look_ahead = u32::try_from(counter).unwrap();
            assert_eq!(
                otp::hotp_check(vectors::OTP_SECRET, &typed, 0, 6, look_ahead),
                Ok(counter)
            );
            if counter > 0 {
                assert_eq!(
                    otp::hotp_check(vectors::OTP_SECRET, &typed, counter + 1, 6, 5),
                    Err(Error::AuthenticationFailed)
                );
            }
        }
    }

    #[test]
    fn rfc6238_totp_sha1() {
        for &(t, code) in vectors::RFC6238_SHA1 {
            let want: u32 = code.parse().unwrap();
            assert_eq!(otp::totp(vectors::OTP_SECRET, t, 8).unwrap(), want, "t={t}");
            let step = t / otp::TOTP_STEP_SECONDS;
            assert_eq!(
                otp::totp_check(vectors::OTP_SECRET, code, t, 8, 0),
                Ok(step)
            );
            // One step of drift either way, with window 1.
            assert_eq!(
                otp::totp_check(vectors::OTP_SECRET, code, t + 30, 8, 1),
                Ok(step)
            );
            if t >= 30 {
                assert_eq!(
                    otp::totp_check(vectors::OTP_SECRET, code, t - 30, 8, 1),
                    Ok(step)
                );
            }
            // Two steps away with window 1: refused.
            assert_eq!(
                otp::totp_check(vectors::OTP_SECRET, code, t + 60, 8, 1),
                Err(Error::AuthenticationFailed)
            );
        }
    }

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(128))]
        #[test]
        fn totp_round_trip(
            secret in proptest::collection::vec(any::<u8>(), 16..64),
            t in 0u64..4_000_000_000,
            digits in 6u32..=8,
            drift in 0u64..=2,
        ) {
            let code = otp::totp(&secret, t, digits).unwrap();
            let typed = format!("{code:0width$}", width = digits as usize);
            let step = t / 30;
            prop_assert_eq!(otp::totp_check(&secret, &typed, t + drift * 30, digits, 2), Ok(step));
            // Any other code fails unless it collides inside the window.
            let other = format!("{:0width$}", (code + 1) % 10u32.pow(digits), width = digits as usize);
            let r = otp::totp_check(&secret, &other, t, digits, 0);
            prop_assert_eq!(r, Err(Error::AuthenticationFailed));
        }
    }
}

#[cfg(feature = "sign-p256")]
mod p256 {
    use super::{Error, h, vectors};
    use crypt_io::sign::EcdsaP256PublicKey;

    fn compressed(uncompressed: &[u8]) -> Vec<u8> {
        let mut out = vec![if uncompressed[64] & 1 == 1 {
            0x03
        } else {
            0x02
        }];
        out.extend_from_slice(&uncompressed[1..33]);
        out
    }

    #[test]
    fn nist_sigver_p256_sha256() {
        for (i, &(point, msg, sig, pass)) in vectors::NIST_P256_SHA256.iter().enumerate() {
            let outcome = EcdsaP256PublicKey::from_sec1(&h(point))
                .and_then(|k| k.check_sha256(&h(msg), &h(sig)));
            assert_eq!(outcome.is_ok(), pass, "case {i}: {outcome:?}");
        }
    }

    fn run(groups: &[vectors::WycheEcdsaGroup], fixed: bool) -> (u32, u32, u32) {
        let (mut valid, mut invalid, mut acceptable) = (0, 0, 0);
        for g in groups {
            let from_sec1 = EcdsaP256PublicKey::from_sec1(&h(g.sec1));
            let from_der = EcdsaP256PublicKey::from_der(&h(g.spki));
            for &(id, msg, sig, result) in g.tests {
                for key in [&from_sec1, &from_der] {
                    let outcome = key.as_ref().map_err(Clone::clone).and_then(|k| {
                        if fixed {
                            k.check_sha256_fixed(&h(msg), &h(sig))
                        } else {
                            k.check_sha256(&h(msg), &h(sig))
                        }
                    });
                    match result {
                        "valid" => assert_eq!(outcome, Ok(()), "tcId {id}"),
                        "invalid" => assert!(outcome.is_err(), "tcId {id} accepted"),
                        _ => {}
                    }
                }
                match result {
                    "valid" => valid += 1,
                    "invalid" => invalid += 1,
                    _ => acceptable += 1,
                }
            }
        }
        (valid, invalid, acceptable)
    }

    #[test]
    fn wycheproof_p256_der() {
        let (valid, invalid, acceptable) = run(vectors::WYCHEPROOF_P256_DER, false);
        println!("p256 der: {valid} valid, {invalid} invalid, {acceptable} acceptable");
        assert!(valid > 50 && invalid > 300);
    }

    #[test]
    fn wycheproof_p256_p1363() {
        let (valid, invalid, acceptable) = run(vectors::WYCHEPROOF_P256_P1363, true);
        println!("p256 p1363: {valid} valid, {invalid} invalid, {acceptable} acceptable");
        assert!(valid > 50 && invalid > 50);
    }

    #[test]
    fn compressed_points_and_coordinates_give_the_same_key() {
        let g = &vectors::WYCHEPROOF_P256_DER[0];
        let (_, msg, sig, _) = *g.tests.iter().find(|t| t.3 == "valid").unwrap();
        let point = h(g.sec1);
        let x: [u8; 32] = point[1..33].try_into().unwrap();
        let y: [u8; 32] = point[33..].try_into().unwrap();
        for key in [
            EcdsaP256PublicKey::from_sec1(&compressed(&point)).unwrap(),
            EcdsaP256PublicKey::from_coordinates(&x, &y).unwrap(),
        ] {
            key.check_sha256(&h(msg), &h(sig)).unwrap();
        }
    }

    #[test]
    fn bad_keys_are_key_errors() {
        let point = h(vectors::WYCHEPROOF_P256_DER[0].sec1);
        let mut off_curve = point.clone();
        off_curve[64] ^= 1;
        for bad in [
            &b""[..],
            &point[..64],
            &off_curve,
            &[0x05; 65][..],
            &point[1..],
        ] {
            assert!(matches!(
                EcdsaP256PublicKey::from_sec1(bad),
                Err(Error::Sign(_))
            ));
        }
        // An SPKI is not a SEC1 point, and the reverse.
        assert!(EcdsaP256PublicKey::from_sec1(&h(vectors::WYCHEPROOF_P256_DER[0].spki)).is_err());
        assert!(EcdsaP256PublicKey::from_der(&point).is_err());
    }

    #[test]
    fn fixed_signature_length_is_enforced() {
        let k = EcdsaP256PublicKey::from_sec1(&h(vectors::WYCHEPROOF_P256_DER[0].sec1)).unwrap();
        for len in [0, 63, 65, 72] {
            assert_eq!(
                k.check_sha256_fixed(b"m", &vec![1u8; len]),
                Err(Error::AuthenticationFailed)
            );
        }
        fn send_sync<T: Send + Sync + Clone>() {}
        send_sync::<EcdsaP256PublicKey>();
    }
}

#[cfg(any(feature = "sign-p256", feature = "sign-ed25519", feature = "sign-rsa"))]
mod webauthn {
    use super::{Error, h, vectors};
    use crypt_io::sign::CosePublicKey;

    fn enabled(alg: i64) -> bool {
        (alg == -7 && cfg!(feature = "sign-p256"))
            || (alg == -8 && cfg!(feature = "sign-ed25519"))
            || (alg == -257 && cfg!(feature = "sign-rsa"))
    }

    #[test]
    fn level3_test_vectors() {
        let mut checked = 0;
        for &(name, alg, cose, msg, sig) in vectors::WEBAUTHN {
            let parsed = CosePublicKey::from_cose_key(&h(cose));
            match alg {
                -7 | -8 | -257 if enabled(alg) => {
                    let key = parsed.unwrap_or_else(|e| panic!("{name}: {e}"));
                    assert_eq!(key.algorithm(), alg);
                    key.check(&h(msg), &h(sig))
                        .unwrap_or_else(|e| panic!("{name}: {e}"));
                    let mut tampered = h(msg);
                    tampered[0] ^= 1;
                    assert_eq!(
                        key.check(&tampered, &h(sig)),
                        Err(Error::AuthenticationFailed),
                        "{name}"
                    );
                    checked += 1;
                }
                -7 | -8 | -257 => {
                    assert!(
                        matches!(parsed, Err(Error::AlgorithmNotEnabled(_))),
                        "{name}"
                    );
                }
                _ => assert_eq!(
                    parsed.unwrap_err(),
                    Error::Sign("COSE key: unsupported algorithm"),
                    "{name}"
                ),
            }
        }
        println!("webauthn: {checked} assertions checked");
    }

    fn es256_key() -> Vec<u8> {
        h(vectors::WEBAUTHN.iter().find(|v| v.1 == -7).unwrap().2)
    }

    #[test]
    fn malformed_and_inconsistent_keys_are_refused() {
        let good = es256_key();
        // a5 01 02 03 26 20 01 21 58 20 <x> 22 58 20 <y>
        assert_eq!(
            &good[..8],
            &[0xa5, 0x01, 0x02, 0x03, 0x26, 0x20, 0x01, 0x21]
        );
        let mut trailing = good.clone();
        trailing.push(0x00);
        let mut wrong_kty = good.clone();
        wrong_kty[2] = 0x03; // RSA
        let mut wrong_crv = good.clone();
        wrong_crv[6] = 0x02; // P-384
        let mut short_x = good.clone();
        short_x[9] = 0x1f;
        let cases: [(&[u8], &str); 4] = [
            (&trailing, "COSE key: trailing bytes"),
            (&wrong_kty, "COSE key: kty does not match alg"),
            (&wrong_crv, "COSE key: ES256 needs crv P-256"),
            (&short_x, ""),
        ];
        for (bytes, msg) in cases {
            let err = CosePublicKey::from_cose_key(bytes).unwrap_err();
            if !msg.is_empty() && cfg!(feature = "sign-p256") {
                assert_eq!(err, Error::Sign(msg));
            }
        }
        for len in 0..good.len() {
            assert!(
                CosePublicKey::from_cose_key(&good[..len]).is_err(),
                "prefix {len}"
            );
        }
        // Without alg.
        let no_alg = [0xa1, 0x01, 0x02];
        assert_eq!(
            CosePublicKey::from_cose_key(&no_alg).unwrap_err(),
            Error::Sign("COSE key: missing alg")
        );
    }

    #[cfg(feature = "sign-rsa")]
    #[test]
    fn rsa_components_match_der() {
        use crypt_io::sign::RsaPublicKey;
        let generated =
            aws_lc_rs::rsa::KeyPair::generate(aws_lc_rs::rsa::KeySize::Rsa2048).unwrap();
        let spki = aws_lc_rs::encoding::AsDer::<aws_lc_rs::encoding::PublicKeyX509Der>::as_der(
            aws_lc_rs::signature::KeyPair::public_key(&generated),
        )
        .unwrap();
        let from_der = RsaPublicKey::from_der(spki.as_ref()).unwrap();
        // n from the PKCS#1 encoding inside the key; e = 65537, with leading zeros.
        let pkcs1 = aws_lc_rs::signature::KeyPair::public_key(&generated)
            .as_ref()
            .to_vec();
        let n = &pkcs1[pkcs1.len() - 5 - 257 + 1..pkcs1.len() - 5];
        let from_parts =
            RsaPublicKey::from_components(&[&[0u8, 0][..], n].concat(), &[0, 1, 0, 1]).unwrap();
        assert_eq!(from_parts.modulus_bits(), from_der.modulus_bits());
        let sig = {
            let mut s = vec![0u8; generated.public_modulus_len()];
            generated
                .sign(
                    &aws_lc_rs::signature::RSA_PKCS1_SHA256,
                    &aws_lc_rs::rand::SystemRandom::new(),
                    b"m",
                    &mut s,
                )
                .unwrap();
            s
        };
        from_parts.check_pkcs1v15_sha256(b"m", &sig).unwrap();
        assert!(RsaPublicKey::from_components(&[], &[1, 0, 1]).is_err());
        assert!(RsaPublicKey::from_components(n, &[0, 0]).is_err());
    }
}
